/**
 * A workspace edit represents changes to many resources managed in the workspace. The edit
 * should either provide `changes` or `documentChanges`. If documentChanges are present
 * they are preferred over `changes` if the client can handle versioned document edits.
 *
 * Since version 3.13.0 a workspace edit can contain resource operations as well. If resource
 * operations are present clients need to execute the operations in the order in which they
 * are provided. So a workspace edit for example can consist of the following two changes:
 * (1) a create file a.txt and (2) a text document edit which insert text into file a.txt.
 *
 * An invalid sequence (e.g. (1) delete file a.txt and (2) insert text into file a.txt) will
 * cause failure of the operation. How the client recovers from the failure is described by
 * the client capability: `workspace.workspaceEdit.failureHandling`
 */
export type Lua_lsp_WorkspaceEdit = {
  /**
   * Holds changes to existing resources.
   */
  changes?: {
    [key in Extract<Lua_lsp_DocumentUri, string | number>]: Lua_lsp_TextEdit[];
  };
  /**
   * Depending on the client capability `workspace.workspaceEdit.resourceOperations` document changes
   * are either an array of `TextDocumentEdit`s to express changes to n different text documents
   * where each text document edit addresses a specific version of a text document. Or it can contain
   * above `TextDocumentEdit`s mixed with create, rename and delete file / folder operations.
   *
   * Whether a client supports versioned document edits is expressed via
   * `workspace.workspaceEdit.documentChanges` client capability.
   *
   * If a client neither supports `documentChanges` nor `workspace.workspaceEdit.resourceOperations` then
   * only plain `TextEdit`s using the `changes` property are supported.
   */
  documentChanges?: (
    | Lua_lsp_TextDocumentEdit
    | Lua_lsp_CreateFile
    | Lua_lsp_RenameFile
    | Lua_lsp_DeleteFile
  )[];
  /**
   * A map of change annotations that can be referenced in `AnnotatedTextEdit`s or create, rename and
   * delete file / folder operations.
   *
   * Whether clients honor this property depends on the client capability `workspace.changeAnnotationSupport`.
   *
   * @since 3.16.0
   */
  changeAnnotations?: {
    [key in Extract<
      Lua_lsp_ChangeAnnotationIdentifier,
      string | number
    >]: Lua_lsp_ChangeAnnotation;
  };
};

export type Lua_lsp_WorkspaceEditClientCapabilities = {
  /**
   * The client supports versioned document changes in `WorkspaceEdit`s
   */
  documentChanges?: boolean;
  /**
   * The resource operations the client supports. Clients should at least
   * support 'create', 'rename' and 'delete' files and folders.
   *
   * @since 3.13.0
   */
  resourceOperations?: Lua_lsp_ResourceOperationKind[];
  /**
   * The failure handling strategy of a client if applying the workspace edit
   * fails.
   *
   * @since 3.13.0
   */
  failureHandling?: Lua_lsp_FailureHandlingKind;
  /**
   * Whether the client normalizes line endings to the client specific
   * setting.
   * If set to `true` the client will normalize line ending characters
   * in a workspace edit to the client-specified new line
   * character.
   *
   * @since 3.16.0
   */
  normalizesLineEndings?: boolean;
  /**
   * Whether the client in general supports change annotations on text edits,
   * create file, rename file and delete file changes.
   *
   * @since 3.16.0
   */
  changeAnnotationSupport?: Lua_lsp_ChangeAnnotationsSupportOptions;
  /**
   * Whether the client supports `WorkspaceEditMetadata` in `WorkspaceEdit`s.
   *
   * @since 3.18.0
   */
  metadataSupport?: boolean;
  /**
   * Whether the client supports snippets as text edits.
   *
   * @since 3.18.0
   */
  snippetEditSupport?: boolean;
};

