export type Lua_TSNode = NativeReference<{}> & {
  /**
   * Get the node's immediate parent.
   * Prefer |TSNode:child_with_descendant()|
   * for iterating over the node's ancestors.
   */
  parent: () => Promise<Lua_TSNode | null>;
  /**
   * Get the node's next sibling.
   */
  next_sibling: () => Promise<Lua_TSNode | null>;
  /**
   * Get the node's previous sibling.
   */
  prev_sibling: () => Promise<Lua_TSNode | null>;
  /**
   * Get the node's next named sibling.
   */
  next_named_sibling: () => Promise<Lua_TSNode | null>;
  /**
   * Get the node's previous named sibling.
   */
  prev_named_sibling: () => Promise<Lua_TSNode | null>;
  /**
   * Iterates over all the direct children of {TSNode}, regardless of whether
   * they are named or not.
   * Returns the child node plus the eventual field name corresponding to this
   * child node.
   */
  iter_children: () => Promise<NativeIterator<[Lua_TSNode, string | null]>>;
  /**
   * Returns a list of all the node's children that have the given field name.
   * @param name
   */
  field: (name: string) => Promise<Lua_TSNode[]>;
  /**
   * Get the node's number of children.
   */
  child_count: () => Promise<number>;
  /**
   * Get the node's child at the given {index}, where zero represents the first
   * child.
   * @param index
   */
  child: (index: number) => Promise<Lua_TSNode | null>;
  /**
   * Get the node's number of named children.
   */
  named_child_count: () => Promise<number>;
  /**
   * Returns a list of the node's named children.
   */
  named_children: () => Promise<Lua_TSNode[]>;
  /**
   * Get the node's named child at the given {index}, where zero represents the
   * first named child.
   * @param index
   */
  named_child: (index: number) => Promise<Lua_TSNode | null>;
  /**
   * Get the node's child that contains {descendant} (includes {descendant}).
   *
   * For example, with the following node hierarchy:
   *
   * ```
   * a -> b -> c
   *
   * a:child_with_descendant(c) == b
   * a:child_with_descendant(b) == b
   * a:child_with_descendant(a) == nil
   * ```
   * @param descendant
   */
  child_with_descendant: (descendant: Lua_TSNode) => Promise<Lua_TSNode | null>;
  /**
   * Get the node's start position. Return three values: the row, column and
   * total byte count (all zero-based).
   */
  start: () => Promise<[number, number, number]>;
  /**
   * Get the node's end position. Return three values: the row, column and
   * total byte count (all zero-based).
   */
  end_: () => Promise<[number, number, number]>;
  /**
   * Get the range of the node.
   *
   * Return four or six values:
   *
   * - start row
   * - start column
   * - start byte (if {include_bytes} is `true`)
   * - end row
   * - end column
   * - end byte (if {include_bytes} is `true`)
   * @param include_bytes
   */
  range: ((
    include_bytes: true,
  ) => Promise<[number, number, number, number, number, number]>) &
    ((
      include_bytes?: false | null,
    ) => Promise<[number, number, number, number]>);
  /**
   * Get the node's type as a string.
   */
  type: () => Promise<string>;
  /**
   * Get the node's type as a numerical id.
   */
  symbol: () => Promise<number>;
  /**
   * Check if the node is named. Named nodes correspond to named rules in the
   * grammar, whereas anonymous nodes correspond to string literals in the
   * grammar.
   */
  named: () => Promise<boolean>;
  /**
   * Check if the node is missing. Missing nodes are inserted by the parser in
   * order to recover from certain kinds of syntax errors.
   */
  missing: () => Promise<boolean>;
  /**
   * Check if the node is extra. Extra nodes represent things like comments,
   * which are not required by the grammar but can appear anywhere.
   */
  extra: () => Promise<boolean>;
  /**
   * Check if a syntax node has been edited.
   */
  has_changes: () => Promise<boolean>;
  /**
   * Check if the node is a syntax error or contains any syntax errors.
   */
  has_error: () => Promise<boolean>;
  /**
   * Get an S-expression representing the node as a string.
   */
  sexpr: () => Promise<string>;
  /**
   * Get a unique identifier for the node inside its own tree.
   *
   * No guarantees are made about this identifier's internal representation,
   * except for being a primitive Lua type with value equality (so not a
   * table). Presently it is a (non-printable) string.
   *
   * Note: The `id` is not guaranteed to be unique for nodes from different
   * trees.
   */
  id: () => Promise<Uint8Array>;
  /**
   * Get the |TSTree| of the node.
   */
  tree: () => Promise<Lua_TSTree>;
  /**
   * Get the smallest node within this node that spans the given range of (row,
   * column) positions
   * @param start_row
   * @param start_col
   * @param end_row
   * @param end_col
   */
  descendant_for_range: (
    start_row: number,
    start_col: number,
    end_row: number,
    end_col: number,
  ) => Promise<Lua_TSNode | null>;
  /**
   * Get the smallest named node within this node that spans the given range of
   * (row, column) positions
   * @param start_row
   * @param start_col
   * @param end_row
   * @param end_col
   */
  named_descendant_for_range: (
    start_row: number,
    start_col: number,
    end_row: number,
    end_col: number,
  ) => Promise<Lua_TSNode | null>;
  /**
   * Check if {node} refers to the same node within the same tree.
   * @param node
   */
  equal: (node: Lua_TSNode) => Promise<boolean>;
  /**
   * Return the number of bytes spanned by this node.
   */
  byte_length: () => Promise<number>;
} & TreeSitterNodeOperations;

/**
 * Reference to an object held by the treesitter library that is used as a
 * component of the |vim.treesitter.Query| for language feature support.
 * See |treesitter-query| for more about queries or |vim.treesitter.query.parse()|
 * for an example of how to obtain a query object.
 */
export type Lua_TSQuery = NativeReference<{}> & {
  /**
   * Get information about the query's patterns and captures.
   *
   */
  inspect: () => Promise<Lua_TSQueryInfo>;
  /**
   * Disable a specific capture in this query; once disabled the capture cannot be re-enabled.
   * {capture_name} should not include a leading "@".
   *
   * Example: To disable the `@variable.parameter` capture from the vimdoc highlights query:
   * ```lua
   * local query = vim.treesitter.query.get('vimdoc', 'highlights')
   * query.query:disable_capture("variable.parameter")
   * vim.treesitter.get_parser():parse()
   * ```
   * @param capture_name
   */
  disable_capture: (capture_name: string) => Promise<RpcValue>;
  /**
   * Disable a specific pattern in this query; once disabled the pattern cannot be re-enabled.
   * The {pattern_index} for a particular match can be obtained with |:Inspect!|, or by reading
   * the source of the query (i.e. from |vim.treesitter.query.get_files()|).
   *
   * Example: To disable `|` links in vimdoc but keep other `@markup.link`s highlighted:
   * ```lua
   * local link_pattern = 9 -- from :Inspect!
   * local query = vim.treesitter.query.get('vimdoc', 'highlights')
   * query.query:disable_pattern(link_pattern)
   * local tree = vim.treesitter.get_parser():parse()[1]
   * ```
   * @param pattern_index
   */
  disable_pattern: (pattern_index: number) => Promise<RpcValue>;
};

export type Lua_TSQueryInfo = {
  captures: string[];
  patterns: { [key: number]: (number | string)[][] };
};

export type Lua_TSQueryMatch = NativeReference<{}> & {
  captures: () => Promise<{ [key: number]: Lua_TSNode[] }>;
  info: () => Promise<[number, number]>;
};

export type Lua_TSTree = NativeReference<{}> & {
  /**
   * Return the root node of this tree.
   */
  root: () => Promise<Lua_TSNode>;
  /**
   *  stylua: ignore
   * @param start_byte
   * @param end_byte_old
   * @param end_byte_new
   * @param start_row
   * @param start_col
   * @param end_row_old
   * @param end_col_old
   * @param end_row_new
   * @param end_col_new
   *
   */
  edit: (
    start_byte: number,
    end_byte_old: number,
    end_byte_new: number,
    start_row: number,
    start_col: number,
    end_row_old: number,
    end_col_old: number,
    end_row_new: number,
    end_col_new: number,
  ) => Promise<Lua_TSTree>;
  /**
   * Returns a copy of the `TSTree`.
   */
  copy: () => Promise<Lua_TSTree>;
  /**
   * @param include_bytes
   *
   */
  included_ranges: ((include_bytes: true) => Promise<Lua_Range6[]>) &
    ((include_bytes: false) => Promise<Lua_Range4[]>);
};

