export type Lua_vim_lsp_Client = NativeReference<{
  /**
   * Each buffer's last used `languageId`.
   */
  attached_buffers: { [key: number]: string };
  /**
   * Capabilities provided by the client (editor or tool), at startup.
   */
  capabilities: Lua_lsp_ClientCapabilities;
  /**
   * See [vim.lsp.ClientConfig].
   * (default: `false`)
   */
  exit_timeout: number | boolean;
  /**
   * Experimental client flags:
   */
  flags: Lua_vim_lsp_Client_Flags;
  /**
   * The id allocated to the client.
   */
  id: number;
  initialized?: true | null;
  /**
   * See [vim.lsp.ClientConfig].
   */
  name: string;
  /**
   * See [vim.lsp.ClientConfig].
   */
  offset_encoding: "utf-8" | "utf-16" | "utf-32";
  /**
   * The current pending requests in flight to the server. Entries are key-value
   * pairs with the key being the request id while the value is a table with
   * `type`, `bufnr`, and `method` key-value pairs. `type` is either "pending"
   * for an active request, or "cancel" for a cancel request. It will be
   * "complete" ephemerally while executing |LspRequest| autocmds when replies
   * are received from the server.
   */
  requests: {
    [key: number]: {
      type: string;
      bufnr: number;
      method: Lua_vim_lsp_protocol_Method;
    } | null;
  };
  /**
   * See [vim.lsp.ClientConfig].
   */
  root_dir?: string | null;
  /**
   * Response from the server sent on `initialize` describing the server's capabilities.
   */
  server_capabilities: Lua_lsp_ServerCapabilities;
  /**
   * Response from the server sent on `initialize` describing server information (e.g. version).
   */
  server_info?: Lua_lsp_ServerInfo | null;
  /**
   * See [vim.lsp.ClientConfig].
   */
  settings: Lua_lsp_LSPObject;
  /**
   * See [vim.lsp.ClientConfig].
   */
  workspace_folders?: Lua_lsp_WorkspaceFolder[] | null;
}> & {
  initialize: () => Promise<RpcValue>;
  /**
   * Sends a request to the server.
   *
   * This is a thin wrapper around {client.rpc.request} with some additional
   * checks for capabilities and handler availability.
   *
   * @param method LSP method name.
   * @param params LSP request params.
   * @returns Response |lsp-handler| for this method.
   * @param bufnr (default: 0) Buffer handle, or 0 for current.
   *     If it is `false`, then it will always be `false` (the client has shutdown).
   *                             `nil` is request failed.
   * to cancel the-request.
   * @see |vim.lsp.buf_request_all()|
   */
  request: (
    method: Lua_vim_lsp_protocol_Method_ClientToServer_Request,
    params?: Record<string, RpcValue> | RpcValue[],
    bufnr?: number,
  ) => Promise<
    [
      Lua_lsp_ResponseError | null,
      RpcValue,
      Lua_lsp_HandlerContext,
      (Record<string, RpcValue> | RpcValue[]) | null,
    ]
  >;
  /**
   * Sends a request to the server and synchronously waits for the response.
   *
   * This is a wrapper around |Client:request()|
   *
   * @param method LSP method name.
   * @param params LSP request params.
   * @param timeout_ms Maximum time in milliseconds to wait for
   *                                a result. Defaults to 1000
   * @param bufnr (default: 0) Buffer handle, or 0 for current.
   * @returns `result` and `err` from the |lsp-handler|.
   *                 `nil` is the request was unsuccessful
   * @returns On timeout, cancel or error, where `err` is a
   *                 string describing the failure reason.
   * @see |vim.lsp.buf_request_sync()|
   */
  request_sync: (
    method: Lua_vim_lsp_protocol_Method_ClientToServer_Request,
    params: Record<string, RpcValue> | RpcValue[],
    timeout_ms?: number | null,
    bufnr?: number,
  ) => Promise<
    [
      {
        err?: Lua_lsp_ResponseError | null;
        result: RpcValue;
      } | null,
      string | null,
    ]
  >;
  /**
   * Sends a notification to an LSP server.
   *
   * @param method LSP method name.
   * @param params LSP request params.
   * @param bufnr Buffer associated with notification.
   * @returns indicating if the notification was successful.
   *                        If it is false, then the client has shutdown.
   */
  notify: (
    method: Lua_vim_lsp_protocol_Method_ClientToServer_Notification,
    params?: (Record<string, RpcValue> | RpcValue[]) | null,
    bufnr?: number | null,
  ) => Promise<boolean>;
  /**
   * Cancels a request with a given request id.
   *
   * @param id id of request to cancel
   * @returns indicating if the notification was successful.
   * @see |Client:notify()|
   */
  cancel_request: (id: number) => Promise<boolean>;
  /**
   * Stops a client, optionally with force after a timeout.
   *
   * By default this sends a "shutdown" request to the server, escalating to force-stop if the server
   * has not exited after `self.exit_timeout` milliseconds (unless `exit_timeout=false`).
   * Calling stop() on a client that was previously requested to shutdown, will escalate to
   * force-stop immediately, regardless of `force` (or `self.exit_timeout` if `force=nil`).
   *
   * Note: Forcing shutdown while a server is busy writing out project or index files can lead to
   * file corruption.
   *
   * @param force (default: `self.exit_timeout`) Decides whether to force-stop the server.
   * - `false`: Do not force-stop after "shutdown" request.
   * - `nil`: Defaults to `exit_timeout` from |vim.lsp.ClientConfig|.
   * - `true`: Force-stop after "shutdown" request.
   * - number: Wait up to `force` milliseconds before force-stop.
   */
  stop: (force?: number | boolean) => Promise<RpcValue>;
  /**
   * Checks whether a client is stopped.
   *
   * @returns true if client is stopped or in the process of being
   * stopped; false otherwise
   */
  is_stopped: () => Promise<boolean>;
  /**
   * Execute a lsp command, either via client command function (if available)
   * or via workspace/executeCommand (if supported by the server)
   *
   * @param cmd
   * @param context
   * @param handler only called if a server command
   */
  exec_cmd: (
    cmd: Lua_lsp_Command,
    context?: {
      bufnr?: number;
    },
    handler?: Lua_lsp_Handler,
  ) => Promise<RpcValue>;
  /**
   * Runs the on_attach function from the client's config if it was defined.
   * Useful for buffer-local setup.
   * @param bufnr Buffer number
   */
  on_attach: (bufnr: number) => Promise<RpcValue>;
  /**
   * Checks if a client supports a given method.
   * Always returns true for unknown off-spec methods.
   *
   * Note: Some language server capabilities can be file specific.
   * @param method
   * @param bufnr
   */
  supports_method: (
    method:
      | Lua_vim_lsp_protocol_Method_ClientToServer
      | Lua_vim_lsp_protocol_Method_Registration,
    bufnr?: number,
  ) => Promise<boolean>;
};

export type Lua_vim_lsp_Client_Flags = {
  /**
   * Allow using incremental sync for buffer edits
   * (default: `true`)
   */
  allow_incremental_sync?: boolean;
  /**
   * Debounce `didChange` notifications to the server by the given number in milliseconds.
   * (default: `150`)
   */
  debounce_text_changes?: number;
};

export type Lua_vim_lsp_ClientConfig = {
  /**
   * Callback which can modify parameters before they are sent to the server. Invoked before LSP
   * "initialize" phase (after `cmd` is invoked), where `params` is the parameters being sent to the
   * server and `config` is the config passed to |vim.lsp.start()|.
   *
   * Hint: use |vim.tbl_deep_extend()| to set nested fields easily.
   * ```lua
   * before_init = function(_, config)
   *   config.settings = vim.tbl_deep_extend('force',
   *     config.settings,
   *     { tailwindCSS = { experimental = { configFile = find_tailwind_global_css() } } }
   *   )
   * end
   * ```
   */
  before_init?: never;
  /**
   * Map overriding the default capabilities defined by |vim.lsp.protocol.make_client_capabilities()|,
   * passed to the language server on initialization. Hint: use make_client_capabilities() and modify
   * its result.
   * - Note: To send an empty dictionary use |vim.empty_dict()|, else it will be encoded as an
   *   array.
   */
  capabilities?: Lua_lsp_ClientCapabilities;
  /**
   * Command `string[]` that launches the language server (treated as in |jobstart()|, must be
   * absolute or on `$PATH`, shell constructs like "~" are not expanded), or function that creates an
   * RPC client (or an in-process |lsp-server|). Function receives a `dispatchers` table and the
   * resolved `config`, and must return an object in the form of |vim.lsp.rpc.Client|.
   *
   * Example (list):
   * ```lua
   * cmd = { 'flow', 'lsp' }
   * ```
   * Example (function):
   * ```lua
   * cmd = function(dispatchers, config)
   *   local cmd = vim.fn.executable('flow') == 1 and { 'flow', 'lsp' } or { 'npx', '--no-install', 'flow', 'lsp' }
   *   return vim.lsp.rpc.start(cmd, dispatchers)
   * end
   * ```
   *
   * - See |vim.lsp.rpc.Client|.
   * - For TCP there is a builtin RPC client factory: |vim.lsp.rpc.connect()|
   */
  cmd: string[] | never;
  /**
   * Directory where the `cmd` process is launched when `cmd` is a string array. Defaults to
   * `root_dir` when available, then the current working directory.
   */
  cmd_cwd?: string;
  /**
   * Environment variables passed to the LSP process on spawn. Non-string values are coerced to
   * string.
   * Example:
   * ```lua
   * { PORT = 8080, HOST = '0.0.0.0' }
   * ```
   */
  cmd_env?: Record<string, RpcValue> | RpcValue[];
  /**
   * Map of client-defined commands overriding the global |vim.lsp.commands|.
   */
  commands?: { [key: string]: never };
  /**
   * Daemonize the server process so that it runs in a separate process group from Nvim.
   * Nvim will shutdown the process on exit, but if Nvim fails to exit cleanly this could leave
   * behind orphaned server processes.
   * (default: `true`)
   */
  detached?: boolean;
  /**
   * Decides if/when to force-stop the server after sending the "shutdown" request. See |Client:stop()|.
   * Note: when Nvim itself is exiting,
   * - `false`: Nvim will not force-stop LSP server(s).
   * - `true`: Nvim will force-stop LSP server(s) that did not comply with the "shutdown" request.
   * - `number`: Nvim will wait up to `exit_timeout` milliseconds before performing force-stop.
   * (default: `false`)
   */
  exit_timeout?: number | boolean;
  /**
   * Experimental client flags:
   */
  flags?: Lua_vim_lsp_Client_Flags;
  /**
   * Language ID as string. Defaults to the buffer filetype.
   */
  get_language_id?: never;
  /**
   * Map of LSP method names to |lsp-handler|s.
   */
  handlers?: { [key: string]: never };
  /**
   * Values to pass in the initialization request as `initializationOptions`. See `initialize` in
   * the LSP spec.
   */
  init_options?: Lua_lsp_LSPObject;
  /**
   * Name in logs and user messages.
   * (default: client-id)
   */
  name?: string;
  /**
   * Called "position encoding" in LSP spec. The encoding that the LSP server expects, used for
   * communication. Not validated. Can be modified in `on_init` before text is sent to the server.
   */
  offset_encoding?: "utf-8" | "utf-16" | "utf-32";
  /**
   * Callback invoked when client attaches to a buffer.
   */
  on_attach?: Lua_elem_or_list<never>;
  /**
   * Callback invoked when the client operation throws an error. `code` is a number describing the error.
   * Other arguments may be passed depending on the error kind.  See `vim.lsp.rpc.client_errors`
   * for possible errors. Use `vim.lsp.rpc.client_errors[code]` to get human-friendly name.
   */
  on_error?: never;
  /**
   * Callback invoked on client exit.
   *   - code: exit code of the process
   *   - signal: number describing the signal used to terminate (if any)
   *   - client_id: client handle
   */
  on_exit?: Lua_elem_or_list<never>;
  /**
   * Callback invoked after LSP "initialize", where `result` is a table of `capabilities` and
   * anything else the server may send. For example, clangd sends `init_result.offsetEncoding` if
   * `capabilities.offsetEncoding` was sent to it. You can only modify the `client.offset_encoding`
   * here before any notifications are sent.
   */
  on_init?: Lua_elem_or_list<never>;
  /**
   * Directory where the LSP server will base its workspaceFolders, rootUri, and rootPath on initialization.
   */
  root_dir?: string;
  /**
   * Map of language server-specific settings, decided by the client. Sent to the LS if requested via
   * `workspace/configuration`. Keys are case-sensitive.
   */
  settings?: Lua_lsp_LSPObject;
  /**
   * Passed directly to the language server in the initialize request. Invalid/empty values will
   * (default: "off")
   */
  trace?: "off" | "messages" | "verbose";
  /**
   * List of workspace folders passed to the language server. For backwards compatibility rootUri and
   * rootPath are derived from the first workspace folder in this list. Can be `null` if the client
   * supports workspace folders but none are configured. See `workspaceFolders` in LSP spec.
   */
  workspace_folders?: Lua_lsp_WorkspaceFolder[];
  /**
   * Server requires a workspace (no "single file" support). Note: Without
   * a workspace, cross-file features (navigation, hover) may or may not work depending on the
   * language server, even if the server doesn't require a workspace.
   * (default: `false`)
   */
  workspace_required?: boolean;
};

